import {TourGuideClient} from "../Tour";

/**
 * dotsWrapperHtmlString
 *
 * FIX: Plain template string statt DOM-Element-Erstellung nur zum
 * Auslesen von outerHTML. Spart unnötige DOM-Operationen.
 */
function dotsWrapperHtmlString(): string {
    return `<div class="tg-dialog-dots" id="tg-dialog-dots"></div>`
}

/**
 * computeDots
 *
 * FIX: `this`-Kontext statt Parameter (konsistent mit backdrop.ts/dialog.ts)
 * FIX: Template-String-Building statt DOM-Element-Erstellung pro Dot
 * FIX: einfache Memoization - vermeidet unnötige Neuberechnung, wenn sich
 * weder activeStep noch die Anzahl der Steps geändert hat (relevant bei
 * häufigen Aufrufen durch Resize-/Scroll-Handler).
 *
 * @this TourGuideClient
 */
function computeDots(this: TourGuideClient): string {
    if (!this.tourSteps.length) return ""

    // Memoization: nur neu berechnen, wenn sich relevante Werte geändert haben
    const cacheKey = `${this.activeStep}:${this.tourSteps.length}`
    if (this._dotsCache?.key === cacheKey) {
        return this._dotsCache.html
    }

    let dotsHtml = ""
    for (let i = 0; i < this.tourSteps.length; i++) {
        const isActive = i === this.activeStep
        dotsHtml += `<span class="tg-dot${isActive ? ' tg-dot-active' : ''}"></span>`
    }

    this._dotsCache = {key: cacheKey, html: dotsHtml}
    return dotsHtml
}

export {dotsWrapperHtmlString, computeDots}
