import {TourGuideClient} from "../Tour";
import {getOverflowAncestors} from "@floating-ui/dom";

/**
 * Kurzes Zeitfenster (ms), um zu erkennen, ob durch scrollIntoView()
 * überhaupt eine Scroll-Bewegung ausgelöst wurde. Smooth-Scrolling
 * feuert das erste `scroll`-Event praktisch im nächsten Frame (~16ms),
 * daher reicht ein kurzes Fenster aus, um "wird gescrollt" von
 * "keine Bewegung nötig" zuverlässig zu unterscheiden.
 *
 * FIX: Von vorher 1000ms auf 150ms reduziert. Der vorherige, lange
 * Fallback-Timeout griff in der Praxis SEHR häufig (jedes Mal, wenn das
 * Zielelement bereits sichtbar war und daher gar kein scroll-Event
 * ausgelöst wurde), was zu einer wahrnehmbaren ~1s-Verzögerung bei
 * JEDEM Step führte - inkl. dem Eindruck eines "Sprungs" statt einer
 * fließenden Bewegung, da Dialog/Backdrop währenddessen komplett
 * eingefroren blieben und sich erst nach der langen Pause abrupt neu
 * positionierten.
 */
const SCROLL_DETECTION_WINDOW_MS = 150

/**
 * Zeitspanne (ms) ohne weiteres scroll-Event, nach der wir eine
 * tatsächlich laufende Scroll-Bewegung als abgeschlossen betrachten.
 */
const SCROLL_IDLE_THRESHOLD_MS = 100

/**
 * isSufficientlyInView
 *
 * Prüft synchron und ohne jede Wartezeit, ob ein Element bereits
 * ausreichend innerhalb des sichtbaren Viewports liegt, unter
 * Berücksichtigung von `autoScrollOffset`. Damit lässt sich der
 * teuerste Fall (Element ist schon sichtbar, Scrollen wäre unnötig)
 * OHNE jede künstliche Wartezeit überspringen.
 *
 * @param el - Zielelement
 * @param offset - zusätzlicher Sicherheitsabstand (siehe `autoScrollOffset`-Option)
 */
function isSufficientlyInView(el: HTMLElement, offset: number): boolean {
    const rect = el.getBoundingClientRect()
    return (
        rect.top >= offset &&
        rect.left >= 0 &&
        rect.bottom <= (window.innerHeight - offset) &&
        rect.right <= window.innerWidth
    )
}

/**
 * scrollToTarget
 *
 * FIX: `this`-Kontext statt Parameter (konsistent mit dem Rest der Codebase).
 * FIX: TODO gelöst - erkennt tatsächliches Scroll-Ende statt eines festen,
 * ggf. zu kurzen/langen Timeouts im Aufrufer-Code.
 * FIX: Horcht nicht mehr nur auf `window`, sondern auf ALLE scrollbaren
 * Vorfahren des Zielelements (via floating-ui's getOverflowAncestors).
 * Das deckt auch Fälle ab, in denen das Ziel innerhalb eines inneren
 * scrollbaren Containers (z.B. <div style="overflow:auto">) liegt und
 * scrollIntoView() dort scrollt, ohne ein window-scroll-Event auszulösen.
 * Inklusive Fallback-Timeout für den Fall, dass gar kein scroll-Event
 * ausgelöst wird.
 *
 * @this TourGuideClient
 * @param targetElem - Element, zu dem gescrollt werden soll
 */
function scrollToTarget(this: TourGuideClient, targetElem: HTMLElement): Promise<true> {
    if (!targetElem.isConnected) {
        if (this.options.debug) {
            console.warn("scrollToTarget: target element is not connected to the DOM")
        }
        return Promise.resolve(true)
    }

    const offset = this.options.autoScrollOffset ?? 0

    // FIX: Element bereits sichtbar - keine Bewegung nötig, sofort auflösen
    // ohne überhaupt scrollIntoView() aufzurufen oder auf Events zu warten.
    if (isSufficientlyInView(targetElem, offset)) {
        return Promise.resolve(true)
    }

    return new Promise((resolve) => {
        let idleTimer: ReturnType<typeof setTimeout> | undefined
        let detectionTimer: ReturnType<typeof setTimeout> | undefined
        let scrollDetected = false

        const scrollTargets = Array.from(
            new Set<EventTarget>([window, ...getOverflowAncestors(targetElem)])
        )

        const finish = () => {
            scrollTargets.forEach((target) => target.removeEventListener("scroll", onScroll))
            if (idleTimer) clearTimeout(idleTimer)
            if (detectionTimer) clearTimeout(detectionTimer)
            resolve(true)
        }

        const onScroll = () => {
            scrollDetected = true
            if (idleTimer) clearTimeout(idleTimer)
            idleTimer = setTimeout(finish, SCROLL_IDLE_THRESHOLD_MS)
        }

        // Kurzes Detection-Fenster: Falls in dieser Zeit KEIN scroll-Event
        // eintrifft, ist mit sehr hoher Wahrscheinlichkeit keine Bewegung
        // im Gange (oder sie ist bereits/synchron abgeschlossen) - sofort
        // auflösen, statt unnötig zu warten.
        detectionTimer = setTimeout(() => {
            if (!scrollDetected) finish()
        }, SCROLL_DETECTION_WINDOW_MS)

        scrollTargets.forEach((target) =>
            target.addEventListener("scroll", onScroll, {passive: true})
        )

        targetElem.scrollIntoView({
            behavior: this.options.autoScrollSmooth ? "smooth" : "auto",
            block: "end",
            inline: "nearest",
        })
    })
}

export default scrollToTarget
