/**
 * Standard-Timeout (ms), nach dem das Warten auf ein Element als
 * fehlgeschlagen abgebrochen wird, um hängende MutationObserver zu
 * vermeiden (siehe Erläuterung unten).
 */
const DEFAULT_WAIT_TIMEOUT_MS = 5000

/**
 * waitForElm
 *
 * Wartet darauf, dass ein Element, das dem übergebenen CSS-Selektor
 * entspricht, im DOM erscheint.
 *
 * FIX: Timeout ergänzt - ohne Begrenzung blieb der MutationObserver bei
 * einem nie erscheinenden Element (z.B. nach einem vorherigen Fehler
 * beim Dialog-Rendering) UNBEGRENZT aktiv und beobachtete dauerhaft
 * jede DOM-Änderung der gesamten Seite (`document.body`, `subtree: true`)
 * - ein Memory-/Performance-Leak-Risiko, besonders relevant bei
 * SPA-Routing mit vielen aufeinanderfolgenden Seitenwechseln.
 * FIX: Doppelten `querySelector`-Aufruf im Erfolgsfall des initialen
 * Checks vermieden.
 * FIX: Explizite Typisierung (Parameter + Rückgabewert).
 *
 * @param selector - CSS-Selektor des gesuchten Elements
 * @param timeoutMs - maximale Wartezeit in ms, bevor das Promise rejected wird
 * @returns Promise, das mit dem gefundenen Element aufgelöst wird
 */
function waitForElm(selector: string, timeoutMs: number = DEFAULT_WAIT_TIMEOUT_MS): Promise<Element> {
    return new Promise((resolve, reject) => {
        const existing = document.querySelector(selector)
        if (existing) {
            resolve(existing)
            return
        }

        let timeoutId: ReturnType<typeof setTimeout> | undefined

        const observer = new MutationObserver(() => {
            const found = document.querySelector(selector)
            if (found) {
                cleanup()
                resolve(found)
            }
        })

        const cleanup = () => {
            observer.disconnect()
            if (timeoutId) clearTimeout(timeoutId)
        }

        timeoutId = setTimeout(() => {
            cleanup()
            reject(new Error(`waitForElm: timed out after ${timeoutMs}ms waiting for "${selector}"`))
        }, timeoutMs)

        observer.observe(document.body, {
            childList: true,
            subtree: true
        })
    })
}

export default waitForElm
