import {TourGuideClient} from "../Tour";
import {computeBackdropPosition} from "./backdrop";
import {computeDialogPosition} from "./dialog";

/**
 * Dauer der CSS-Transition für Backdrop-/Dialog-Positionswechsel (in ms).
 * Muss mit der entsprechenden `transition`-Duration in der CSS-Klasse
 * `.animate-position` übereinstimmen.
 */
const POSITION_ANIMATION_DURATION_MS = 300

/**
 * computeTourPositions
 *
 * FIX: `new Promise(async...)`-Anti-Pattern durch `async function` ersetzt.
 * FIX: `.call(this)` für computeBackdropPosition/computeDialogPosition,
 * da beide seit dem Umbau auf `this: TourGuideClient` statt Parameter
 * umgestellt wurden.
 * FIX: Abschließender Timeout wird nur noch angewendet, wenn `dialogAnimate`
 * aktiv ist - andernfalls löst das Promise sofort auf, ohne künstliche
 * Verzögerung für Konsumenten, die z.B. `await updatePositions()` nutzen.
 */
async function computeTourPositions(this: TourGuideClient): Promise<true> {
    /**
     * Update overlay position
     */
    this.backdrop.style.display = "block"
    await computeBackdropPosition.call(this)

    /**
     * Update dialog position
     */
    this.dialog.style.display = 'block'

    const shouldAnimate = this.options.dialogAnimate

    if (shouldAnimate && this.isVisible) {
        this.dialog.classList.add('animate-position') // add transition class
    }

    await computeDialogPosition.call(this)

    this.isVisible = true

    if (!shouldAnimate) {
        // Keine Transition aktiv - sofort auflösen, keine künstliche Verzögerung
        return true
    }

    // Match timeout with CSS transition & smooth scroll
    return new Promise((resolve) => {
        setTimeout(() => {
            this.dialog.classList.remove('animate-position') // cancel after CSS transition complete
            resolve(true)
        }, POSITION_ANIMATION_DURATION_MS)
    })
}

export default computeTourPositions
