import {TourGuideClient} from "../Tour";

/**
 * handleClose
 *
 * Beendet die Tour: verbirgt Dialog/Backdrop, entfernt Listener und
 * ruft Exit-Callbacks auf.
 *
 * FIX: `new Promise(async...)`-Anti-Pattern durch async/await/throw ersetzt.
 * FIX: Lock (`_promiseWaiting`) wird jetzt via try/finally IMMER wieder
 * freigegeben - auch wenn `_globalBeforeExitCallback` einen Fehler wirft.
 * Vorher konnte ein fehlschlagender Callback die Tour dauerhaft in einem
 * "Promise waiting"-Zustand einfrieren, aus dem kein exit()/nextStep()/
 * prevStep() mehr herauskam.
 * FIX: `_globalAfterExitCallback` wird awaited und Fehler werden im
 * Debug-Modus geloggt statt komplett verschluckt zu werden.
 */

async function handleClose(this: TourGuideClient): Promise<true> {
    if (this._exitLock) {
        throw new Error("Promise waiting")
    }

    this._exitLock = true
    try {
        if (this._globalBeforeExitCallback) {
            await this._globalBeforeExitCallback()
        }

        this.dialog.style.display = "none"
        this.backdrop.style.display = "none"
        this.isVisible = false
        if (!this.options.rememberStep) this.activeStep = 0

        if (this.options.debug) console.info("Tour exited")

        document.body.classList.remove('tg-no-interaction')

        await this.destroyListeners()

        return true
    } finally {
        this._exitLock = false

        if (this._globalAfterExitCallback) {
            Promise.resolve(this._globalAfterExitCallback()).catch((e) => {
                if (this.options.debug) console.warn(e)
            })
        }
    }
}

export default handleClose
