import {TourGuideClient} from "../Tour";

/**
 * Generic helper to validate & assign a callback to a property on the
 * TourGuideClient instance. Reduces duplication across all onX handlers
 * below and ensures consistent error messages.
 *
 * FIX: zentrale Validierungslogik statt 5x Copy-Paste
 *
 *
 * @param instance - Die TourGuideClient-Instanz, auf der der Callback gesetzt wird
 * @param propertyKey - Der Property-Key, unter dem der Callback gespeichert wird
 * @param providedCallback - Der zu validierende und zuzuweisende Callback
 * @param callbackName - Name für die Fehlermeldung (z.B. "onFinish")
 */
function assignCallback<K extends keyof TourGuideClient>(
    instance: TourGuideClient,
    propertyKey: K,
    providedCallback: TourGuideClient[K],
    callbackName: string
): void {
    if (typeof providedCallback !== "function") {
        throw new Error(`Provided callback for ${callbackName} was not a function`)
    }
    instance[propertyKey] = providedCallback
}

/**
 * handleOnFinish
 * @param providedCallback - Callback, der beim Abschluss der Tour aufgerufen wird
 */
function handleOnFinish(
    this: TourGuideClient,
    providedCallback: () => (void | Promise<unknown>)
): void {
    assignCallback(this, "_globalFinishCallback", providedCallback, "onFinish")
}

/**
 * handleOnBeforeExit
 * @param providedCallback - Callback, der vor dem Beenden der Tour aufgerufen wird
 */
function handleOnBeforeExit(
    this: TourGuideClient,
    providedCallback: () => (void | Promise<unknown>)
): void {
    assignCallback(this, "_globalBeforeExitCallback", providedCallback, "onBeforeExit")
}

/**
 * handleOnAfterExit
 * @param providedCallback - Callback, der nach dem Beenden der Tour aufgerufen wird
 */
function handleOnAfterExit(
    this: TourGuideClient,
    providedCallback: () => (void | Promise<unknown>)
): void {
    assignCallback(this, "_globalAfterExitCallback", providedCallback, "onAfterExit")
}

/**
 * handleOnBeforeStepChange
 *
 * FIX: Signatur korrigiert auf (currentStepIndex, stepIndex) - passend
 * zum tatsächlichen Typ von `_globalBeforeChangeCallback` in Tour.ts
 * und zu dem, wie der Callback in handleVisitStep.ts tatsächlich
 * aufgerufen wird.
 *
 * @param providedCallback - Callback, der vor jedem Step-Wechsel aufgerufen wird
 */
function handleOnBeforeStepChange(
    this: TourGuideClient,
    providedCallback: (currentStepIndex: number, stepIndex: number) => (void | Promise<unknown>)
): void {
    assignCallback(this, "_globalBeforeChangeCallback", providedCallback, "onBeforeStepChange")
}

/**
 * handleOnAfterStepChange
 *
 * FIX: Signatur korrigiert auf (previousStepIndex, stepIndex) - passend
 * zum tatsächlichen Typ von `_globalAfterChangeCallback` in Tour.ts.
 *
 * @param providedCallback - Callback, der nach jedem Step-Wechsel aufgerufen wird
 */
function handleOnAfterStepChange(
    this: TourGuideClient,
    providedCallback: (previousStepIndex: number, stepIndex: number) => (void | Promise<unknown>)
): void {
    assignCallback(this, "_globalAfterChangeCallback", providedCallback, "onAfterStepChange")
}

export {
    handleOnFinish,
    handleOnBeforeExit,
    handleOnAfterExit,
    handleOnBeforeStepChange,
    handleOnAfterStepChange
}
