import {TourGuideClient} from "../Tour";
import waitForElm from "../util/util_wait_for_element";
import computeTourSteps from "../core/steps";

/**
 * handleTourStart
 *
 * Startet die Tour: berechnet Steps, navigiert zum ersten (oder
 * gemerkten) Step und initialisiert Event-Listener.
 *
 * FIX: `new Promise(async...)`-Anti-Pattern durch async/await/throw ersetzt.
 * FIX: Fehlendes `return` nach Fehler in `visitStep()` behoben - vorher
 * lief der Code trotz gescheiterter Navigation weiter und initialisierte
 * Listener auf einem potenziell inkonsistenten Zustand.
 * FIX: `.call(this)` für computeTourSteps (this-basierte Signatur).
 * FIX: Lock-Schutz via `_navigationLock` NUR um die Steps-Berechnung
 * gelegt, NICHT um den `visitStep()`-Aufruf - da `visitStep()`
 * (genauer: handleVisitStep) den Lock bereits selbst verwaltet. Würde
 * der Lock hier zusätzlich um visitStep() gelegt, würde
 * handleVisitStep sofort mit "Promise waiting" abbrechen, da der Lock
 * schon gesetzt wäre (Deadlock-artiges Verhalten).
 *
 * @param group - Optionaler Gruppen-Key, um nur eine bestimmte Step-Gruppe zu starten
 */
async function handleTourStart(this: TourGuideClient, group?: string): Promise<true> {
    if (this.isVisible) {
        if (this.options.debug) console.warn('Tour already active')
        throw new Error("Tour already active")
    }

    if (this._navigationLock) {
        throw new Error("Promise waiting")
    }

    if (group) this.group = group
    if (this.options.debug) console.info('Start tour')

    /**
     * Tour steps
     *
     * NOTE: Lock wird NUR für diesen Block gehalten, da computeTourSteps
     * selbst keinen eigenen Lock verwaltet (anders als visitStep()).
     */
    this._navigationLock = true
    try {
        await computeTourSteps.call(this)
    } catch (e) {
        if (this.options.debug) console.warn(e)
        throw e
    } finally {
        this._navigationLock = false
    }

    /**
     * Go to step
     *
     * NOTE: Kein manueller Lock hier - handleVisitStep() verwaltet
     * `_navigationLock` bereits selbst für die gesamte Dauer der
     * Navigation (inkl. beforeEnter/afterEnter-Callbacks etc.).
     */
    try {
        await this.visitStep(this.activeStep)
    } catch (e) {
        if (this.options.debug) console.warn(e)
        throw e
    }

    /**
     * Ensure dialog is rendered in DOM
     */
    await waitForElm('.tg-dialog').then(async () => {
        /**
         * Init listeners
         * Double initialization is handled inside of handler
         */
        await this.initListeners()

        // Add transition class to dialog after additional delay to prevent flying in from random position
        if (this.options.dialogAnimate) this.dialog.classList.add('animate-position')

        if (!this.options.exitOnClickOutside) {
            document.body.classList.add('tg-no-interaction')
        }
    }).catch((e) => {
        if (this.options.debug) console.warn(e)
    })

    return true
}

export default handleTourStart
