import {TourGuideClient} from "../Tour";
import type {TourGuideOptions} from "../core/options";
import {renderDialogHtml, updateDialogHtml} from "../core/dialog";
import waitForElm from "../util/util_wait_for_element";

/**
 * handleSetOptions
 *
 * Aktualisiert die Tour-Optionen zur Laufzeit und spiegelt Änderungen
 * im Dialog wider (Neu-Rendering, Backdrop-Attribute, Listener-Reinit).
 *
 * FIX: `.call(this)` für renderDialogHtml/updateDialogHtml ergänzt
 * (this-basierte Signatur seit dem Umbau dieser Module).
 * FIX: Lock-Schutz via `_navigationLock` ergänzt, um Kollisionen mit
 * einer laufenden Navigation (goToStep) zu verhindern - vergleichbar
 * mit handleRefreshTour.ts.
 * FIX: Unnötigen `as TourGuideClient`-Cast entfernt.
 *
 * @param options - Teilmenge von TourGuideOptions, die aktualisiert werden soll
 */
async function handleSetOptions(this: TourGuideClient, options: TourGuideOptions): Promise<TourGuideClient> {
    if (!options) return this

    if (this._navigationLock) {
        throw new Error("Promise waiting")
    }

    this._navigationLock = true
    try {
        /**
         * Update options
         *
         * NOTE: Shallow merge via Object.assign. Für die meisten Optionen
         * (Strings, Booleans, Zahlen) ist das korrekt. Bei `steps` (Array)
         * wird das bestehende Array vollständig durch das neue ersetzt,
         * nicht zusammengeführt - das entspricht der bisherigen, bewussten
         * "Steps komplett neu setzen"-Semantik von setOptions() im
         * Unterschied zu addSteps() (siehe handleAddStep.ts), das gezielt
         * einzelne Steps ergänzt.
         */
        Object.assign(this.options, options)

        /**
         * Backdrop
         */
        this.computeBackdropAttributes()

        /**
         * Dialog
         */
        try {
            const htmlResp = await renderDialogHtml.call(this)
            if (htmlResp) this.dialog.innerHTML = htmlResp
        } catch (e) {
            if (this.options.debug) console.warn(e)
        }

        // Re-populate the dialog content
        try {
            await updateDialogHtml.call(this)
        } catch (e) {
            if (this.options.debug) console.warn(e)
        }

        /**
         * Ensure dialog is visible & rendered in DOM
         */
        if (this.isVisible) {
            await waitForElm('.tg-dialog').then(async () => {
                /**
                 * Re-Init listeners
                 * Double initialization is handled inside of handler
                 */
                await this.destroyListeners()
                await this.initListeners()

                // Add transition class to dialog after additional delay to prevent flying in from random position
                // if (this.options.dialogAnimate) setTimeout(() => {
                //     this.dialog.classList.add('animate-position')
                // }, 600)

                return true
            }).catch((e) => {
                if (this.options.debug) console.warn(e)
            })
        }

        return this
    } finally {
        this._navigationLock = false
    }
}

export default handleSetOptions
