import {TourGuideClient} from "../Tour";

const FINISHED_TOURS_STORAGE_KEY = "tg_tours_complete"

/**
 * getCompletedTours
 *
 * Liest die Liste abgeschlossener Tour-Gruppen sicher aus localStorage.
 * FIX: try/catch für Umgebungen ohne localStorage-Zugriff (privater
 * Modus, SSR, deaktivierter Storage - würde vorher zum Absturz führen).
 * FIX: `getItem()` statt direktem Property-Zugriff für klares,
 * standardkonformes Verhalten.
 */
function getCompletedTours(): string[] {
    try {
        const raw = localStorage.getItem(FINISHED_TOURS_STORAGE_KEY)
        if (!raw) return []
        return raw.split(',').filter(Boolean)
    } catch {
        return []
    }
}

/**
 * setCompletedTours
 *
 * FIX: `setItem()`/`removeItem()` statt direkter Property-Zuweisung.
 * Behebt zwei Bugs aus dem Original:
 * 1. `localStorage.tg_tours_complete = [...]` verließ sich auf
 *    implizites `Array.prototype.toString()` (zufällig funktional,
 *    aber fragil und unklar).
 * 2. `localStorage.tg_tours_complete = null` speicherte fälschlich den
 *    literalen String "null" statt den Eintrag zu entfernen - dadurch
 *    wurde `getIsFinished` nach einem `delFinishedTour("all")`-Aufruf
 *    weiterhin fälschlich "truthy" ausgewertet.
 */
function setCompletedTours(tours: string[], debug: boolean): void {
    try {
        if (tours.length === 0) {
            localStorage.removeItem(FINISHED_TOURS_STORAGE_KEY)
        } else {
            localStorage.setItem(FINISHED_TOURS_STORAGE_KEY, tours.join(','))
        }
    } catch (e) {
        if (debug) console.warn("Could not persist finished tour state:", e)
    }
}

/**
 * handleFinishTour
 *
 * Markiert die Tour-Gruppe als abgeschlossen und beendet die Tour optional.
 *
 * FIX: Verwendet den separaten `_navigationLock` statt des vorher
 * geteilten `_promiseWaiting`.
 * FIX: Reentrancy-sicher via `_isInternalCall`-Flag - wird `finishTour`
 * aus `handleVisitStep` heraus aufgerufen (Tour-Ende durch Navigation),
 * hält der aufrufende Kontext den `_navigationLock` bereits; ein
 * erneuter Lock-Check hier würde fälschlich fehlschlagen. Bei einem
 * DIREKTEN, externen Aufruf (`tour.finishTour()`) wird der Lock jedoch
 * regulär geprüft und gesetzt, um parallele Navigation zu verhindern.
 * FIX: `exit()` läuft jetzt über den komplett separaten `_exitLock`
 * (siehe handleClose.ts) und wird daher NICHT vom Navigation-Lock
 * blockiert - die Tour kann so auch während einer laufenden Navigation
 * sauber beendet werden.
 * FIX: localStorage-Zugriffe über sichere Helper statt fehleranfälliger
 * direkter Property-Zuweisung.
 *
 * @param exit - Tour nach Abschluss automatisch schließen (default: true)
 * @param tourGroup - Gruppen-Key, der als abgeschlossen markiert wird
 * @param _isInternalCall - **Nicht Teil der öffentlichen API.** Wird
 * ausschließlich von handleVisitStep.ts gesetzt, wenn der
 * Navigation-Lock bereits vom aufrufenden Kontext gehalten wird.
 */
async function handleFinishTour(
    this: TourGuideClient,
    exit: boolean = true,
    tourGroup: string = "tour",
    _isInternalCall: boolean = false
): Promise<boolean> {
    if (this._navigationLock && !_isInternalCall) {
        throw new Error("Promise waiting")
    }

    // Nur sperren, wenn wir nicht bereits innerhalb eines laufenden,
    // gesperrten Navigations-Vorgangs aufgerufen werden.
    const acquiredLock = !this._navigationLock
    if (acquiredLock) this._navigationLock = true

    try {
        if (this._globalFinishCallback) {
            try {
                await this._globalFinishCallback()
            } catch (e) {
                if (this.options.debug) console.warn(e)
                return false
            }
        }

        if (this.options.completeOnFinish) {
            const completedTours = getCompletedTours()
            if (!completedTours.includes(tourGroup)) {
                completedTours.push(tourGroup)
                setCompletedTours(completedTours, Boolean(this.options.debug))
            }
        }

        if (exit) await this.exit()
        this.activeStep = 0

        return true
    } finally {
        if (acquiredLock) this._navigationLock = false
    }
}

/**
 * getIsFinished
 * @param tourGroup
 */
function getIsFinished(this: TourGuideClient, tourGroup: string = 'tour'): boolean {
    return getCompletedTours().includes(tourGroup)
}

/**
 * delFinishedTour
 *
 * FIX: Nutzt jetzt `removeItem()` über `setCompletedTours([], ...)`
 * statt der fehlerhaften `= null`-Zuweisung.
 *
 * @param tourGroup - Gruppen-Key, oder "all" um alle Einträge zu löschen
 */
function delFinishedTour(this: TourGuideClient, tourGroup: string = 'tour'): void {
    if (tourGroup === "all") {
        setCompletedTours([], Boolean(this.options.debug))
        return
    }
    const remaining = getCompletedTours().filter((x) => x !== tourGroup)
    setCompletedTours(remaining, Boolean(this.options.debug))
}

export default handleFinishTour
export {getIsFinished, delFinishedTour}
