import type {TourGuideOptions} from "../core/options";

/**
 * getDefaultOptions
 *
 * FIX: Von statischem Objekt-Literal auf Factory-Funktion umgestellt.
 * Der wichtigste Grund: `steps: []` war vorher ein EINZIGES, modul-
 * globales Array. Da `TourGuideClient`-Instanzen ihre Optionen nur per
 * flachem Spread (`{ ...defaultOptions, ...options }`) klonen, teilten
 * sich ALLE Instanzen ohne eigene `steps`-Option dasselbe Array-Objekt.
 * Ein `handleAddStep()`-Aufruf auf Instanz A (`this.options.steps.push(...)`)
 * mutierte dadurch auch die "leere" Steps-Liste von Instanz B, C, etc.
 *
 * Mit einer Factory-Funktion erhält jeder Aufruf (= jede neue
 * TourGuideClient-Instanz) ein frisches, unabhängiges `steps`-Array.
 *
 * FIX: `satisfies` statt `as` - TypeScript prüft dadurch aktiv, ob das
 * Objekt zum `TourGuideOptions`-Typ passt (Tippfehler bei Property-
 * Namen oder falsche Wertetypen werden zur Compile-Zeit erkannt),
 * behält aber trotzdem die konkreten Literal-Typen bei (z.B.
 * `stepDotsPlacement: "footer"` bleibt exakt `"footer"`, nicht `string`).
 *
 * FIX: `debug` Default von `true` auf `false` geändert - eine
 * Bibliothek sollte in Produktionsumgebungen standardmäßig keine
 * Konsolen-Ausgaben erzeugen, sofern der Konsument es nicht explizit
 * anfordert.
 */
function getDefaultOptions(): TourGuideOptions {
    return {
        // -----------------------------------------------------------
        // Scroll behaviour
        // -----------------------------------------------------------
        autoScroll: true,
        autoScrollSmooth: true,
        autoScrollOffset: 20,

        // -----------------------------------------------------------
        // Backdrop
        // -----------------------------------------------------------
        backdropClass: "",
        backdropAnimate: true,
        backdropColor: "rgba(20,20,21,0.84)",
        targetPadding: 30,

        // -----------------------------------------------------------
        // Dialog
        // -----------------------------------------------------------
        dialogClass: "",
        allowDialogOverlap: false,
        dialogZ: 999,
        dialogWidth: 0,
        dialogMaxWidth: 340,
        dialogAnimate: true,
        // dialogPlacement bewusst weggelassen (optional, kein sinnvoller
        // Default - floating-ui greift intern auf "bottom" zurück)

        // -----------------------------------------------------------
        // Buttons & Labels
        // -----------------------------------------------------------
        nextLabel: "Next",
        prevLabel: "Back",
        finishLabel: "Finish",
        hideNext: false,
        hidePrev: false,
        showButtons: true,
        closeButton: true,

        // -----------------------------------------------------------
        // Progress indicators
        // -----------------------------------------------------------
        showStepDots: true,
        stepDotsPlacement: "footer",
        showStepProgress: true,
        progressBar: "",

        // -----------------------------------------------------------
        // Behaviour / Interaction
        // -----------------------------------------------------------
        completeOnFinish: true,
        keyboardControls: true,
        exitOnEscape: true,
        exitOnClickOutside: true,
        rememberStep: false,
        activeStepInteraction: true,
        debug: false,
        elementTimeout: 5000,

        // -----------------------------------------------------------
        // Steps
        // -----------------------------------------------------------
        // FIX: Frisches Array pro Funktionsaufruf statt geteilter
        // Modul-Referenz - siehe Erläuterung oben.
        steps: [],
    } satisfies TourGuideOptions
}

export default getDefaultOptions
