import {TourGuideClient} from "../Tour";
import computeTourSteps from "../core/steps";
import {renderDialogHtml, updateDialogHtml} from "../core/dialog";
import waitForElm from "../util/util_wait_for_element";

/**
 * handleRefreshTour
 *
 * Berechnet Tour-Steps, Backdrop-Attribute und Dialog komplett neu.
 * Genutzt z.B. nach dynamischen DOM-Änderungen, die neue `data-tg-tour`-
 * Elemente einführen oder bestehende entfernen.
 *
 * FIX: `new Promise(async...)`-Anti-Pattern entfernt.
 * FIX: Fehlendes `return` nach Fehlern behoben - vorher lief der Code
 * bei einem Fehler in `computeTourSteps` trotzdem weiter und berechnete
 * Backdrop/Dialog auf Basis eines fehlerhaften/leeren Step-Zustands.
 * FIX: `.call(this)` für computeTourSteps (this-basierte Signatur).
 * FIX: Lock-Schutz via `_navigationLock` ergänzt, um Überlappung mit
 * einer laufenden Navigation (goToStep) zu verhindern.
 */
async function handleRefreshTour(this: TourGuideClient): Promise<true> {
    if (this._navigationLock) {
        throw new Error("Promise waiting")
    }

    this._navigationLock = true
    try {
        /**
         * Tour steps
         */
        await computeTourSteps.call(this)

        /**
         * Backdrop
         */
        this.computeBackdropAttributes()

        /**
         * Dialog
         */
        await this.refreshDialog()

        return true
    } finally {
        this._navigationLock = false
    }
}

/**
 * handleRefreshDialog
 *
 * Rendert das Dialog-HTML komplett neu (z.B. nach Options-Änderungen)
 * und aktualisiert Inhalt, Position und Event-Listener.
 *
 * FIX: `new Promise(async...)`-Anti-Pattern entfernt.
 * FIX: Fehlendes `return` nach `reject()`-Aufruf behoben.
 * FIX: `.call(this)` für renderDialogHtml/updateDialogHtml.
 * FIX: Konsistente Fehlerbehandlung - Fehler bei renderDialogHtml
 * werden (wie zuvor) nur im Debug-Modus geloggt und die Funktion läuft
 * weiter (HTML-Neuaufbau ist "best effort"), während ein Fehler bei
 * updateDialogHtml (Datenaktualisierung) die Funktion jetzt korrekt
 * mit einem Error abbricht statt nur zu loggen und trotzdem
 * weiterzulaufen.
 *
 * NOTE: Kein eigener Lock-Check hier, da diese Funktion sowohl
 * eigenständig (öffentliche API `tour.refreshDialog()`) als auch von
 * `handleRefreshTour` (dort bereits gesperrt) aufgerufen wird. Bei
 * direktem externen Aufruf ist das Risiko einer Kollision mit
 * `goToStep` gering, da hier keine `activeStep`/`tourSteps`-Mutation
 * stattfindet - nur DOM-Refresh. Sollte sich das als unzureichend
 * erweisen, kann hier ebenfalls `_navigationLock` ergänzt werden.
 */
async function handleRefreshDialog(this: TourGuideClient): Promise<true> {
    /**
     * Hard refresh dialog HTML - for option updates or hard refresh methods
     */
    try {
        const htmlResp = await renderDialogHtml.call(this)
        if (htmlResp) this.dialog.innerHTML = htmlResp
    } catch (e) {
        if (this.options.debug) console.warn(e)
    }

    /**
     * Update tour guide HTML
     */
    try {
        await updateDialogHtml.call(this)
    } catch (e) {
        if (this.options.debug) console.warn(e)
        throw e
    }

    /**
     * Update backdrop & dialog positions & display
     */
    await this.updatePositions()

    /**
     * Ensure dialog is visible & rendered in DOM
     */
    if (this.isVisible) {
        await waitForElm('.tg-dialog').then(async () => {
            /**
             * Re-Init listeners
             * Double initialization is handled inside of handler
             */
            await this.destroyListeners()
            await this.initListeners()

            // Add transition class to dialog after additional delay to prevent flying in from random position
            // if (this.options.dialogAnimate) setTimeout(() => {
            //     this.dialog.classList.add('animate-position')
            // }, 600)

            return true
        }).catch((e) => {
            if (this.options.debug) console.warn(e)
        })
    }

    return true
}

export default handleRefreshTour
export {handleRefreshDialog}
